use xiom.io;

use xiom.string;
use xiom.convert;
fn add_stock(inv: &mut Map[Str, Int], item: Str, amount: Int) {
  let current = match inv.get(&item) { Some(c) => c, None => 0 };
  inv.insert(item, current + amount);
}

fn remove_stock(inv: &mut Map[Str, Int], item: Str, amount: Int) -> Bool {
  let current = match inv.get(&item) { Some(c) => c, None => 0 };
  if current >= amount {
    inv.insert(item, current - amount);
    return true;
  }
  return false;
}

fn main() -> Int {
  var inv: Map[Str, Int] = Map[Str, Int].new();
  inv.insert("apples", 50);
  inv.insert("bananas", 30);
  inv.insert("milk", 15);

  add_stock(&mut inv, "apples", 20);

  let sale1 = remove_stock(&mut inv, "bananas", 10);
  io.println("Sold 10 bananas: " + convert.bool_to_string(sale1));

  let sale2 = remove_stock(&mut inv, "milk", 100);
  io.println("Sold 100 milk: " + convert.bool_to_string(sale2));

  let apples = match inv.get(&"apples") { Some(c) => c, None => 0 };
  let bananas = match inv.get(&"bananas") { Some(c) => c, None => 0 };
  let milk = match inv.get(&"milk") { Some(c) => c, None => 0 };
  io.println("Apples: " + to_string(apples));
  io.println("Bananas: " + to_string(bananas));
  io.println("Milk: " + to_string(milk));
  return 0;
}
